/bin/bash -c "node -e '
const fs = require(\"fs\");
for (const root of [\"base/packages\", \"packages\"]) {
  const dirs = fs.readdirSync("'`evals/files/workspace-dependencies/${root}`);
  const edges = [];
  for (const dir of dirs) {
    const file = `evals/files/workspace-dependencies/${root}/${dir}/package.json`;
    if (!fs.existsSync(file)) continue;
    const manifest = JSON.parse(fs.readFileSync(file, "utf8"));
    for (const dependency of Object.keys(manifest.dependencies || {})) edges.push(`${manifest.name} -> ${dependency}`);
  }
  console.log(`${root}: ${edges.join(", ") || "(none)"}`);
}
'"'"

